import com.mbeddr.mpsutil.common.graph.Graph;
import org.junit.jupiter.api.Test;
import org.junit.Assert;
import com.google.common.collect.Sets;
import java.util.Arrays;
import com.mbeddr.mpsutil.common.util.Traversal;

public class TraversalClassAPI_NoCycles_Test {
  protected Graph<Integer> graphWithoutCycle = GraphBuilder.start().nodes(1, 2, 3, 4, 5).edge(1, 2).edge(1, 3).edge(2, 4).edge(4, 5).build();
  @Test
  public void test_traverse_Full_OneStart() throws Exception {
    FullTraversal t = new FullTraversal();
    t.doBreadthFirst(1);
    Assert.assertEquals(Sets.newHashSet(1, 2, 3, 4, 5), Sets.newHashSet(t.getVisited()));

  }
  @Test
  public void test_traverse_Full_OneStart_Collect() throws Exception {
    FullTraversal t = new FullTraversal();
    t.doBreadthFirst(1);
    Assert.assertEquals(Sets.newHashSet(1, 2, 3, 4, 5), Sets.newHashSet(t.getVisited()));
  }
  @Test
  public void test_traverse_Full_TwoStarts() throws Exception {
    FullTraversal t = new FullTraversal();
    t.doBreadthFirst(Arrays.asList(2, 3));

    // traversal does not visit "1"
    Assert.assertEquals(Sets.newHashSet(2, 3, 4, 5), Sets.newHashSet(t.getVisited()));

  }
  @Test
  public void test_traverse_Search_OneStart_Success() throws Exception {
    SearchTraversal t = new SearchTraversal(4);
    Assert.assertTrue(t.doBreadthFirst(1));

    // 5 cannot be reached as at 4 the algorithm stops
    Assert.assertEquals(Sets.newHashSet(1, 2, 3, 4), Sets.newHashSet(t.getVisited()));

  }
  @Test
  public void test_traverse_Search_OneStart_NotFound() throws Exception {
    SearchTraversal t = new SearchTraversal(77);
    Assert.assertFalse(t.doBreadthFirst(1));
    Assert.assertEquals(Sets.newHashSet(1, 2, 3, 4, 5), Sets.newHashSet(t.getVisited()));
  }
  @Test
  public void test_traverse_Search_TwoStarts_Success() throws Exception {
    SearchTraversal t = new SearchTraversal(4);
    Assert.assertTrue(t.doBreadthFirst(Arrays.asList(2, 3)));

    // traversal does not visit "1", and also does not count "4"
    Assert.assertEquals(Sets.newHashSet(2, 3, 4), Sets.newHashSet(t.getVisited()));

  }
  @Test
  public void test_traverse_Search_TwoStarts_NotFound() throws Exception {
    SearchTraversal t = new SearchTraversal(1);
    Assert.assertFalse(t.doBreadthFirst(Arrays.asList(2, 3)));

    // traversal does not visit "1"
    Assert.assertEquals(Sets.newHashSet(2, 3, 4, 5), Sets.newHashSet(t.getVisited()));

  }

  public class FullTraversal extends Traversal<Integer> {
    @Override
    protected Iterable<Integer> successorsOf(Integer n) {
      return graphWithoutCycle.getTargets(n);
    }
  }

  public class SearchTraversal extends FullTraversal {
    private int what;
    public SearchTraversal(int what) {
      this.what = what;
    }
    @Override
    protected boolean finishNow(Integer n) {
      return n == what;
    }
  }
}
